'use client'

import * as React from 'react'
import { SloshSlider } from '@/components/spaceui/slosh-slider'

export interface SloshSliderDemoProps {
  height?: number
  corner?: number
  viscosity?: number
  momentum?: number
  tilt?: number
  ring?: boolean
}

export default function Demo({
  height = 40,
  corner = 13,
  viscosity = 15,
  momentum = 55,
  tilt = 45,
  ring = true,
}: SloshSliderDemoProps) {
  const [value, setValue] = React.useState(42)
  return (
    <div className="flex w-full max-w-md flex-col gap-3 px-6">
      <SloshSlider
        value={value}
        onValueChange={setValue}
        height={Number(height)}
        corner={Number(corner)}
        viscosity={Number(viscosity)}
        momentum={Number(momentum)}
        tilt={Number(tilt)}
        ring={Boolean(ring)}
      />
      <p className="text-center text-sm tabular-nums text-muted-foreground">{value}</p>
    </div>
  )
}
